<script setup lang="ts">
import {ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import type {SegmentSlip} from '../segmentPayroll'
import PhaseStatus from './PhaseStatus.vue'
import PayBreakdownSummary from './PayBreakdownSummary.vue'
const props=defineProps<{year:string}>(),{api,load,loading,failure,english,r}=usePayrollPage(),rows=ref<SegmentSlip[]>([]),expanded=ref(''),x=(z:string,e:string)=>english()?e:z
watch(()=>props.year,year=>{rows.value=[];expanded.value='';if(/^\d{4}$/.test(year))void load(()=>api().get<SegmentSlip[]>('/my-payroll-segments?year='+year),v=>{rows.value=v})},{immediate:true})
</script>
<template><section class="wf-section"><h3>{{x('我的提前／分段结薪工资单','My independent settlement payslips')}}</h3><PhaseStatus :failure="failure" :loading="loading"/><article v-for="s in rows" :key="s.id" class="wf-section"><h4>{{s.month}} · {{s.companyName}}</h4><p>{{x('本单覆盖','This payslip covers')}} {{s.from}} – {{s.cutoff}}</p><p><strong>{{x('本次应实发','Net payable this settlement')}} SGD {{s.net}}</strong></p><p>{{x('已登记付款／未付','Recorded paid / remaining')}} {{s.paid}} / {{s.remaining}}</p><p class="wf-hint">{{x('同月多份结薪单按不同期间结算；发布不代表银行到账。','Multiple slips in a month cover separate ranges. Publication is not proof of bank receipt.')}}</p><button type="button" :aria-expanded="expanded===s.id" @click="expanded=expanded===s.id?'':s.id">{{x('查看本单明细','View this payslip')}}</button><template v-if="expanded===s.id"><p>{{r(s.basis as 'monthly'|'hourly'|'daily')}} · SGD {{s.rate}} · {{x('本单核准工时','Approved hours in this period')}} {{(s.workSeconds/3600).toFixed(2)}} h · {{x('加班','Overtime')}} {{(s.overtimeSeconds/3600).toFixed(2)}} h<span v-if="s.payableDays!==null"> · {{x('本单应付日／完整月工作日','Payable days this period / full-month working days')}} {{s.payableDays}} / {{s.workingDays??'—'}}</span></p><PayBreakdownSummary :value="s.breakdown" details business-labels/><p v-for="p in s.payments" :key="p.id">{{p.paymentDate}} · {{p.method}} · SGD {{p.amount}} · {{p.reversesId?x('原付款冲正','Reversal'):x('已登记','Recorded')}}</p></template></article><p v-if="!loading&&!rows.length" class="wf-hint">{{x('本年度暂无已发布分段结薪单。','No published independent payslips this year.')}}</p></section></template>
